ee:message.ee:set-payload:
%dw 2.0
output application/json

var cuentaFacturacion = vars.responseBillingOrderById.resultados[0]
var orden = vars.responseOrderById.resultados[0]
---
{
  "Header": {
    "id": orden.'_id' default "",
    "operation": "SetBillingAccount",
    "requestSystem": "WS.BillingLTECorporate",
    "version": "1",
    "type": "IN",
    "reqType": "SYNC",
    "requestDateTime": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss"},
    "responseDateTime": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss"}
  },
  "Body": {
    "Set_BillingAccount": {
      "WSRequestHeader": {
        "system": {
          "name": "Salesforce,",
          "correlationId": orden.'_id' default "",
          "processingServer": "Tibco"
        },
        "property": {
          "Property": {
            "name": "",
            "value": ""
          }
        }
      },
      "WSRequestBody": {
        "id": cuentaFacturacion.idCuentaFacturacion,
        "document_type": orden.cliente.tipoDocumento,
        "document_number": orden.cliente.numeroDocumento,
        "billing_account": do {
            var idCF = cuentaFacturacion.idCuentaFacturacion
            ---
            (orden.cuentasFacturacion filter ($.idCuentaFacturacion == idCF)).cuentaFacturacion[0]
        },
        "parent_billing_account": do {
            var idCF = cuentaFacturacion.idCuentaFacturacion
            ---
            (orden.cuentasFacturacion filter ($.idCuentaFacturacion == idCF)).cuentaPadreFacturacion[0]
        },
        "state": "A",
        "market": orden.cliente.segmento,
        "frequency": "",
        "creator_user": orden.usuario,
        "modifier_user": orden.usuario,
        "email": do {
            var idCF = cuentaFacturacion.idCuentaFacturacion
            ---
            (orden.cuentasFacturacion filter ($.idCuentaFacturacion == idCF)).correoElectronico[0]
        },
        "address": do {
              var idCF = cuentaFacturacion.idCuentaFacturacion
              var direccionFacturacion = (orden.cuentasFacturacion filter ($.idCuentaFacturacion == idCF)).idDireccionFacturacion[0]
              ---
              ((orden.direcciones filter ($.idDireccion == direccionFacturacion))[0].direccion) default ""
          },
        "country": "Colombia",
        "department": do {
              var idCF = cuentaFacturacion.idCuentaFacturacion
              var direccionFacturacion = (orden.cuentasFacturacion filter ($.idCuentaFacturacion == idCF)).idDireccionFacturacion[0]
              ---
              (orden.direcciones filter ($.idDireccion == direccionFacturacion))[0].departamento
          },
        "city": do {
              var idCF = cuentaFacturacion.idCuentaFacturacion
              var direccionFacturacion = (orden.cuentasFacturacion filter ($.idCuentaFacturacion == idCF)).idDireccionFacturacion[0]
              ---
              (orden.direcciones filter ($.idDireccion == direccionFacturacion))[0].municipio
          },
        "neighborhood": "",
        "location": "",
        "stratum": do {
              var idCF = cuentaFacturacion.idCuentaFacturacion
              var direccionFacturacion = (orden.cuentasFacturacion filter ($.idCuentaFacturacion == idCF)).idDireccionFacturacion[0]
              ---
              (orden.direcciones filter ($.idDireccion == direccionFacturacion))[0].cobertura.estrato
          },
        "billing_cycle": do {
            var idCF = cuentaFacturacion.idCuentaFacturacion
            ---
            (orden.cuentasFacturacion filter ($.idCuentaFacturacion == idCF)).cicloFacturacion[0]
        },
        "long_time": "",
        "invoice_type": "",
        "invoice_support": "",
        "type_delivery_invoice": do {
            var idCF = cuentaFacturacion.idCuentaFacturacion
            ---
            (orden.cuentasFacturacion filter ($.idCuentaFacturacion == idCF)).tipoEntregaFactura[0]
        },
        "charging_cycle": "",
        "code_charging_cycle": "",
        "date_cut_billing": do {
            var idCF = cuentaFacturacion.idCuentaFacturacion
            ---
            ((orden.cuentasFacturacion filter ($.idCuentaFacturacion == idCF)) .diaFacturacion[0]) default ""
        },
        "taxes": "",
        "modified_MDM": "1",
        "order_order_related": "",
        "salesforce_invoice_id": cuentaFacturacion.idCuentaFacturacion,
        "set_type": "I"
      }
    }
  }
}

%dw 2.0
output application/json

var cuentaFacturacion = vars.responseBillingOrderById.resultados[0]
var orden = vars.responseOrderById.resultados[0]
---
{
