        "ApplicationObjectKeyID": ""
      },
      "RootParentSalesOrderLineIdentification": {
        "ID": "",
        "BusinessComponentID": "",
        "ApplicationObjectKeyID": ""
      },
      "StatusCode": "",
      "ServiceAddress": {
        "LineOne": ""
      },
      "ItemReference": {
        "ItemIdentification": {
          "ID": "",
          "BusinessComponentID": "",
          "ApplicationObjectKeyID": ""
        },
        "Name": "",
        "ServiceIndicator": true,
