      },
      "AltKey": [
        {
          "AltKeyName": "SysOrg",
          "AltKeyValue": "SF"
        },
        {
          "AltKeyName": "USO",
          "AltKeyValue": "SF"
        },
        {
          "AltKeyName": "BACYT",
          "AltKeyValue": do {
              var idCF = cuentaFacturacion.idCuentaFacturacion
              var direccionFacturacion = (orden.cuentasFacturacion filter ($.idCuentaFacturacion == idCF)).idDireccionFacturacion[0]
              ---
              ((orden.direcciones filter ($.idDireccion == direccionFacturacion))[0].municipio) default ""
          }
        },
        {
          "AltKeyName": "MetodoReclamacion",
          "AltKeyValue": "MetodoReclamacion"
        },
        {
          "AltKeyName": "BACON",
          "AltKeyValue": "Colombia"
        },
        {
          "AltKeyName": "BAAID",
          "AltKeyValue": cuentaFacturacion.idCuentaFacturacion
        },
        {
          "AltKeyName": "ETBFN",
          "AltKeyValue": ""
        },
        {
          "AltKeyName": "BAUSO",
          "AltKeyValue": ""
        },
        {
          "AltKeyName": "ETBLN",
          "AltKeyValue": trim(orden.cliente.nombres default '' + ' ' + orden.cliente.primerApellido default '' + ' ' + orden.cliente.segundoApellido default '')
        },
        {
          "AltKeyName": "Segmento",
          "AltKeyValue": orden.cliente.segmento
        },
        {
          "AltKeyName": "BAADD",
          "AltKeyValue": do {
              var idCF = cuentaFacturacion.idCuentaFacturacion
              var direccionFacturacion = (orden.cuentasFacturacion filter ($.idCuentaFacturacion == idCF)).idDireccionFacturacion[0]
              ---
              ((orden.direcciones filter ($.idDireccion == direccionFacturacion))[0].direccionNormalizada) default ""
          }
        },
        {
          "AltKeyName": "Subsegmento",
          "AltKeyValue": orden.cliente.subSegmento
        },
        {
          "AltKeyName": "PHONE",
          "AltKeyValue": orden.cliente.telefonoMovil default ""
        },
        {
          "AltKeyName": "ETB Facturable",
          "AltKeyValue": "Y"
        }
      ]
    }
  },
  "BillingProcess": {
    "Customer": {
      "FullName": orden.cliente.nombres default '' + ' ' + orden.cliente.primerApellido default '' + ' ' + orden.cliente.segundoApellido default '',
      "ContactInfo": {
        "ContactAddress": {
          "DaneCode": do {
              var idCF = cuentaFacturacion.idCuentaFacturacion
              var direccionFacturacion = (orden.cuentasFacturacion filter ($.idCuentaFacturacion == idCF)).idDireccionFacturacion[0]
              ---
              (orden.direcciones filter ($.idDireccion == direccionFacturacion))[0].codigoMunicipio
          }
        }
      },
      "DocumentType": orden.cliente.tipoDocumento,
      "DocumentNo": orden.cliente.numeroDocumento
    },
    "CustomerBill": {
