          var idCF = cuentaFacturacion.idCuentaFacturacion
          ---
          (orden.cuentasFacturacion filter ($.idCuentaFacturacion == idCF)).cuentaFacturacion[0]
      },
      "InvoicingCycle": do {
          var idCF = cuentaFacturacion.idCuentaFacturacion
          ---
          (orden.cuentasFacturacion filter ($.idCuentaFacturacion == idCF)).cicloFacturacion[0]
      }
    }
  }
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
if (vars.responseMDM == "ERROR")
	(vars.responseArray << {
		"MDM": "Error en envío"
	})
else
	(vars.responseArray << {
		"MDM": vars.responseMDM
	})

%dw 2.0
output application/json
---
if (vars.responseRMCA == "ERROR")
	(vars.responseArray << {
		"RMCA": "Error en envío"
	})
else
	(vars.responseArray << {
		"RMCA": vars.responseMDM
	})

ee:message.ee:set-payload:
%dw 2.0
output application/json

var ordenIdCuenta = vars.responseBillingOrderById.resultados[0]
var cicloFacturacion = vars.initialice.Revchain_Respuesta_Proceso.WsRequestBody.CicloFacturacion
var corte = vars.initialice.Revchain_Respuesta_Proceso.WsRequestBody.Corte
var cuentaFacturacion = vars.initialice.Revchain_Respuesta_Proceso.WsRequestBody.Cuenta_Facturacion

import * from dw::util::Values
---
((if (ordenIdCuenta.cicloFacturacion == null) 
	ordenIdCuenta ++ {"cicloFacturacion": cicloFacturacion} 
else ordenIdCuenta update "cicloFacturacion" with cicloFacturacion)

then ((result) -> 
	(if (result.corte == null) 
		result ++ {"corte": corte} 
	else result update "corte" with corte)

)) then ((res) -> 
	(if (res.cuentaFacturacion == null) 
		res ++ {"cuentaFacturacion": cuentaFacturacion} 
	else res update "cuentaFacturacion" with cuentaFacturacion))

%dw 2.0 output application/json import * from dw::util::Values import mergeWith from dw::core::Objects
var idCuenta = vars.responseBillingOrderById.resultados[0].idCuentaFacturacion
fun actualizarOrden() = (vars.responseOrderById.resultados[0].cuentasFacturacion map ((cuenta, index) -> if (cuenta.idCuentaFacturacion == idCuenta) cuenta mergeWith { "cuentaFacturacion": vars.responseBillingOrderById.resultados[0].cuentaFacturacion, "cicloFacturacion": vars.responseBillingOrderById.resultados[0].cicloFacturacion, "corte": vars.responseBillingOrderById.resultados[0].corte, "fechaCreacion": vars.responseBillingOrderById.resultados[0].fechaCreacion, }
else cuenta )) --- vars.responseOrderById.resultados[0] update "cuentasFacturacion" with actualizarOrden()

%dw 2.0
output application/json
import * from dw::util::Values

var orden = vars.responseOrderById.resultados[0]
var idCF = vars.initialice.Revchain_Respuesta_Proceso.WsRequestBody.Cuenta_Facturacion
fun searchIdCtaFact(idFact) = (orden.cuentasFacturacion filter $.idCuentaFacturacion == idFact)[0].cuentaFacturacion
---
"items": (orden.items map {
    "items": if (searchIdCtaFact($.idCuentaFacturacion) == idCF) (if ($.estadoItem != null ) ($ update "estadoItem" with {
                                                                        "fecha": now(),
                                                                        "codigoEstado": vars.codigoEstado,
                                                                        "nombreEstado": vars.nombreEstado,
                                                                        "observaciones": vars.observaciones
                                                                        }
                                                                    )
		else $ ++ { "estadoItem": {
                        "fecha": now(),
                        "codigoEstado": vars.codigoEstado,
                        "nombreEstado": vars.nombreEstado,
                        "observaciones": vars.observaciones
                        }
        }) else $
}
).items

%dw 2.0
output application/json
var currentAccount = (payload.cuentasFacturacion filter (value, index) -> (value.idCuentaFacturacion == vars.firstItem.idCuentaFacturacion))[0]
---
payload update {
	case cuentasFacturacion at .cuentasFacturacion -> cuentasFacturacion map ((value, index) -> value update {
		case .cuentaFacturacion -> (if ( value.cuentaFacturacion == currentAccount.cuentaFacturacion ) vars.initialice.Revchain_Respuesta_Proceso.WsRequestBody.Cuenta_Facturacion 
									else value.cuentaFacturacion)

		case .cicloFacturacion -> (if ( value.cicloFacturacion == currentAccount.cicloFacturacion ) vars.initialice.Revchain_Respuesta_Proceso.WsRequestBody.CicloFacturacion 
									else value.cicloFacturacion)

		case .diaFacturacion -> (if ( value.diaFacturacion == currentAccount.diaFacturacion ) vars.initialice.Revchain_Respuesta_Proceso.WsRequestBody.Corte 
									else value.diaFacturacion)
	})
}

%dw 2.0
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tem http://tempuri.org/
ns tier http://schemas.datacontract.org/2004/07/Tier.Common
ns ws http://schemas.datacontract.org/2004/07/WS.Gestor.RequestContracts
---
soapenv#Envelope @("xmlns:tem": tem, "xmlns:tier": tier, "xmlns:ws": ws): {
    soapenv#Header: {},
    soapenv#Body: {
        'tem:RespuestaTransaccion': {
            'tem:WSRequestHeader': {
                'tier:system': {
                    'tier:correlationId': correlationId,
                    'tier:name': vars.name,
                    'tier:processingServer': p('generic-notifier.fact')
                }
            },
            'tem:WSRequestBody': {
            	'ws:Descripcion': write(payload, 'application/json'),
            	'ws:Fecha': vars.firstItem.cuentasFacturacion[0].fechaInicioFacturacion as String default '',
                'ws:IdServicio': vars.firstItem.idServicio,
                'ws:NumeroOC': vars.numeroOC,
                'ws:OrdenOM': vars.ordenOM,
                'ws:Resultado': p('generic-notifier.errorCode'),
                'ws:TipoTransaccion': p('generic-notifier.facturacion')
            }
        }
    }
}

%dw 2.0
output application/json
---
{
  sfilluminate: {
	operacion: payload.Operacion,
	orden_om: vars.ordenOM,
	orden_comercial: vars.numeroOC,
	cuenta: vars.initialice.Revchain_Respuesta_Proceso.WsRequestBody.Cuenta_Facturacion,
	external_service_id: vars.firstItem.idServicio,
	fecha_inicio: vars.omOrder.cuentasFacturacion[0].fechaInicioFacturacion as String default '',
	nickname: (vars.firstItem.productos.parametros filter $['nombre'] == p('compRevchain.nemonico'))[0].valor as String default '',
	servicio: (vars.firstItem.productos.parametros filter $['nombre'] == p('compRevchain.servicioFacturador'))[0].valor as String default '',
	plan: [
		{
			nombre: (vars.firstItem.productos.parametros filter $['nombre'] == p('compRevchain.planFacturador'))[0].valor,
			parametros: payload.Parametro map ((item, index) -> {
				nombre: item.Nombre,
				valor: item.Valor
			})
		}
    ],  
    numeros_conexion: {}
  }
}

%dw 2.0
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tem http://tempuri.org/
ns tier http://schemas.datacontract.org/2004/07/Tier.Common
ns ws http://schemas.datacontract.org/2004/07/WS.Gestor.RequestContracts
---
soapenv#Envelope @("xmlns:tem": tem, "xmlns:tier": tier, "xmlns:ws": ws): {
    soapenv#Header: {},
    soapenv#Body: {
        'tem:RespuestaTransaccion': {
            'tem:WSRequestHeader': {
                'tier:system': {
                    'tier:correlationId': correlationId,
                    'tier:name': vars.name,
                    'tier:processingServer': p('generic-notifier.fact')
                }
            },
            'tem:WSRequestBody': {
            	'ws:Descripcion': write(payload, 'application/json'),
            	'ws:Fecha': vars.firstItem.cuentasFacturacion[0].fechaInicioFacturacion as String default '',
                'ws:IdServicio': vars.firstItem.idServicio,
                'ws:NumeroOC': vars.numeroOC,
                'ws:OrdenOM': vars.ordenOM,
                'ws:Resultado': if (vars.resultado == '0') p('generic-notifier.successCode') else p('generic-notifier.errorCode'),
                'ws:TipoTransaccion': p('generic-notifier.facturacion')
            }
        }
    }
}
